

-- 1. CREATE TABLE
DROP TABLE IF EXISTS orders;
CREATE TABLE orders (
    order_id VARCHAR(100),
    order_date DATE,
    customer_id VARCHAR(100),
    product VARCHAR(255),
    shipping_address TEXT,
    payment_method VARCHAR(100),
    order_status VARCHAR(100),
    tracking_number VARCHAR(150),
    coupon_code VARCHAR(100),
    referral_source VARCHAR(150),
    total_price DECIMAL(12,2),
    quantity INT,
    unit_price DECIMAL(12,2),
    items_in_cart INT
);


-- 2. LOAD DATA






-- 3. DATA VALIDATION
SELECT COUNT(*) AS Total_Rows FROM orders;
SELECT * FROM orders LIMIT 10;

SELECT
    SUM(CASE WHEN total_price IS NULL THEN 1 ELSE 0 END) AS Missing_TotalPrice,
    SUM(CASE WHEN quantity IS NULL THEN 1 ELSE 0 END) AS Missing_Quantity,
    SUM(CASE WHEN unit_price IS NULL THEN 1 ELSE 0 END) AS Missing_UnitPrice,
    SUM(CASE WHEN items_in_cart IS NULL THEN 1 ELSE 0 END) AS Missing_ItemsInCart
FROM orders;


-- 4. SELECT
SELECT * FROM orders;

SELECT order_id, order_date, product, order_status, total_price
FROM orders;


-- 5. WHERE

SELECT *
FROM orders
WHERE order_status = 'Delivered';

SELECT order_id, product, total_price
FROM orders
WHERE total_price > 1000;

SELECT order_id, product, quantity
FROM orders
WHERE quantity >= 5;


-- 6. ORDER BY

SELECT order_id, product, total_price
FROM orders
ORDER BY total_price DESC;

SELECT order_id, product, quantity
FROM orders
ORDER BY quantity DESC;

-- ===============================================================
-- 7. BASIC AGGREGATIONS
-- ===============================================================
SELECT COUNT(*) AS Total_Orders FROM orders;

SELECT SUM(total_price) AS Total_Revenue FROM orders;

SELECT ROUND(AVG(total_price), 2) AS Average_Order_Value FROM orders;

SELECT SUM(quantity) AS Total_Units_Sold FROM orders;

SELECT ROUND(AVG(unit_price), 2) AS Average_Unit_Price FROM orders;

-- ===============================================================
-- 8. GROUP BY
-- ===============================================================
SELECT
    product,
    COUNT(*) AS Number_of_Orders,
    SUM(total_price) AS Total_Revenue,
    ROUND(AVG(total_price), 2) AS Average_Order_Value
FROM orders
GROUP BY product
ORDER BY Total_Revenue DESC;

SELECT
    payment_method,
    COUNT(*) AS Number_of_Orders
FROM orders
GROUP BY payment_method
ORDER BY Number_of_Orders DESC;

SELECT
    order_status,
    COUNT(*) AS Number_of_Orders
FROM orders
GROUP BY order_status
ORDER BY Number_of_Orders DESC;

SELECT
    payment_method,
    COUNT(*) AS Number_of_Orders,
    SUM(total_price) AS Total_Revenue,
    ROUND(AVG(total_price), 2) AS Average_Order_Value
FROM orders
GROUP BY payment_method
ORDER BY Total_Revenue DESC;

SELECT
    referral_source,
    COUNT(*) AS Number_of_Orders,
    SUM(total_price) AS Total_Revenue
FROM orders
GROUP BY referral_source
ORDER BY Total_Revenue DESC;

-- ===============================================================
-- 9. HAVING
-- ===============================================================
SELECT
    product,
    COUNT(*) AS Number_of_Orders,
    SUM(total_price) AS Total_Revenue
FROM orders
GROUP BY product
HAVING COUNT(*) >= 10
ORDER BY Total_Revenue DESC;

SELECT
    referral_source,
    COUNT(*) AS Number_of_Orders
FROM orders
GROUP BY referral_source
HAVING COUNT(*) > 50
ORDER BY Number_of_Orders DESC;

-- ===============================================================
-- 10. DATE ANALYSIS
-- ===============================================================
SELECT
    EXTRACT(YEAR FROM order_date) AS Order_Year,
    COUNT(*) AS Number_of_Orders,
    SUM(total_price) AS Total_Revenue
FROM orders
GROUP BY EXTRACT(YEAR FROM order_date)
ORDER BY Order_Year;

SELECT
    EXTRACT(YEAR FROM order_date) AS Order_Year,
    EXTRACT(MONTH FROM order_date) AS Order_Month,
    COUNT(*) AS Number_of_Orders,
    SUM(total_price) AS Total_Revenue
FROM orders
GROUP BY EXTRACT(YEAR FROM order_date), EXTRACT(MONTH FROM order_date)
ORDER BY Order_Year, Order_Month;

-- ===============================================================
-- 11. CUSTOMER ANALYSIS
-- ===============================================================
SELECT
    customer_id,
    COUNT(*) AS Number_of_Orders,
    SUM(total_price) AS Customer_Revenue,
    ROUND(AVG(total_price), 2) AS Average_Order_Value
FROM orders
GROUP BY customer_id
ORDER BY Customer_Revenue DESC;

SELECT
    customer_id,
    COUNT(*) AS Number_of_Orders
FROM orders
GROUP BY customer_id
HAVING COUNT(*) > 1
ORDER BY Number_of_Orders DESC;

-- ===============================================================
-- 12. TOP 10 ANALYSIS
-- ===============================================================
SELECT order_id, product, total_price
FROM orders
ORDER BY total_price DESC
LIMIT 10;

SELECT product, SUM(quantity) AS Units_Sold
FROM orders
GROUP BY product
ORDER BY Units_Sold DESC
LIMIT 10;

-- ===============================================================
-- 13. PERCENTAGE ANALYSIS
-- ===============================================================
SELECT
    order_status,
    COUNT(*) AS Number_of_Orders,
    ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM orders), 2) AS Percentage_of_Orders
FROM orders
GROUP BY order_status
ORDER BY Percentage_of_Orders DESC;

SELECT
    payment_method,
    COUNT(*) AS Number_of_Orders,
    ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM orders), 2) AS Percentage_of_Orders
FROM orders
GROUP BY payment_method
ORDER BY Percentage_of_Orders DESC;

SELECT
    product,
    SUM(total_price) AS Product_Revenue,
    ROUND(SUM(total_price) * 100.0 / (SELECT SUM(total_price) FROM orders), 2) AS Revenue_Percentage
FROM orders
GROUP BY product
ORDER BY Revenue_Percentage DESC;

-- ===============================================================
-- 14. CASE ANALYSIS
-- ===============================================================
SELECT
    CASE
        WHEN total_price < 100 THEN 'Low Value'
        WHEN total_price < 500 THEN 'Medium Value'
        ELSE 'High Value'
    END AS Order_Value_Segment,
    COUNT(*) AS Number_of_Orders,
    SUM(total_price) AS Total_Revenue
FROM orders
GROUP BY
    CASE
        WHEN total_price < 100 THEN 'Low Value'
        WHEN total_price < 500 THEN 'Medium Value'
        ELSE 'High Value'
    END
ORDER BY Total_Revenue DESC;

-- ===============================================================
-- 15. BUSINESS QUESTIONS
-- ===============================================================
-- Product generating the most revenue
SELECT product, SUM(total_price) AS Total_Revenue
FROM orders
GROUP BY product
ORDER BY Total_Revenue DESC
LIMIT 1;

-- Most-used payment method
SELECT payment_method, COUNT(*) AS Number_of_Orders
FROM orders
GROUP BY payment_method
ORDER BY Number_of_Orders DESC
LIMIT 1;

-- Referral source generating the most revenue
SELECT referral_source, SUM(total_price) AS Total_Revenue
FROM orders
GROUP BY referral_source
ORDER BY Total_Revenue DESC
LIMIT 1;

-- Order status with the highest number of orders
SELECT order_status, COUNT(*) AS Number_of_Orders
FROM orders
GROUP BY order_status
ORDER BY Number_of_Orders DESC
LIMIT 1;

-- Overall average order value
SELECT ROUND(AVG(total_price), 2) AS Average_Order_Value
FROM orders;

-- ===============================================================
-- 16. EXECUTIVE SUMMARY QUERY
-- ===============================================================
SELECT
    COUNT(*) AS Total_Orders,
    ROUND(SUM(total_price), 2) AS Total_Revenue,
    ROUND(AVG(total_price), 2) AS Average_Order_Value,
    SUM(quantity) AS Total_Units_Sold,
    COUNT(DISTINCT customer_id) AS Unique_Customers
FROM orders;

